class Solution {
    public boolean isNumber(String s) {
        boolean seenDigit = false, seenDot = false, seenExp = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= '0' && c <= '9') {
                seenDigit = true;
            } else if (c == '.') {
                if (seenDot || seenExp) return false;
                seenDot = true;
            } else if (c == 'e' || c == 'E') {
                if (seenExp || !seenDigit) return false;
                seenExp = true;
                seenDigit = false;
            } else if (c == '+' || c == '-') {
                if (i > 0 && s.charAt(i - 1) != 'e' && s.charAt(i - 1) != 'E') return false;
            } else {
                return false;
            }
        }
        return seenDigit;
    }
}

class Solution {
    public boolean isNumber(String s) {
        // States: 0=start, 1=sign, 2=digit, 3=dot-after-digit, 4=dot-no-digit, 5=digit-after-dot
        // 6=exp, 7=exp-sign, 8=exp-digit
        int state = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= '0' && c <= '9') {
                if (state == 0 || state == 1) state = 2;
                else if (state == 2) state = 2;
                else if (state == 3) state = 5;
                else if (state == 4) state = 5;
                else if (state == 5) state = 5;
                else if (state == 6 || state == 7) state = 8;
                else if (state == 8) state = 8;
                else return false;
            } else if (c == '+' || c == '-') {
                if (state == 0) state = 1;
                else if (state == 6) state = 7;
                else return false;
            } else if (c == '.') {
                if (state == 0 || state == 1) state = 4;
                else if (state == 2) state = 3;
                else return false;
            } else if (c == 'e' || c == 'E') {
                if (state == 2 || state == 3 || state == 5) state = 6;
                else return false;
            } else {
                return false;
            }
        }
        return state == 2 || state == 3 || state == 5 || state == 8;
    }
}
